/**
 * [FS-WECHAT-GROUPNAME] 微信群的会话标题以前存的是数字群 ID（微信只给一串 id，不给群名）。
 * 入站现在带着 conversation_name，这里把 DSH 会话标题和库里的 title 一起改回真群名。
 */
async retitleWechatSession(row, chat) {
	if (row === null || row === undefined || chat?.chatType !== 'group') return;
	const name = String(chat.title ?? '').trim();
	const targetId = String(chat.targetId ?? '');
	if (name === '' || name === targetId) return;
	const title = `微信群·${sanitizeName(name, targetId)}`;
	if (String(row.title ?? '') === title) return;
	try {
		const titles = service(this.ctx, 'sessionTitle');
		const live = this.agentsService()?.get?.(row.session_id);
		const target = live?.session ?? live;
		if (target !== undefined && target !== null) titles?.rename?.(target, title);
	} catch { /* 标题不影响功能 */ }
	try { this.db.prepare('UPDATE chat_session SET title = ? WHERE id = ?').run(title, row.id); } catch { /* 老库没这一列就算了 */ }
	row.title = title;
	this.log('info', `[fish-soul] 微信群会话标题改为 ${title}`);
}

